function lireAge(texte, rappel) {
  const age = Number(texte);
  if (!Number.isInteger(age) || age < 0 || age > 120) {
    rappel(new Error("âge invalide"));
    return;
  }
  rappel(null, age);
}

function compteARebours(n, chaque, fin) {
  if (n === 0) {
    fin();
    return;
  }
  chaque(n);
  setTimeout(() => compteARebours(n - 1, chaque, fin), 1);
}
